// The fixture was generated by the original Python/NetworkX engine. The TypeScript port must give
// the same answers: a wrong "+" or "-" would teach a blind student the wrong thing.
import { describe, expect, it } from "vitest";
import { MODELS } from "@/lib/models";
import golden from "./fixtures/python-engine-golden.json";

// The Python engine listed loops in a different order on every run (hash-seeded), so compare
// lists of loops by id rather than by position.
function canon(value: unknown): unknown {
  if (Array.isArray(value)) {
    const items = value.map(canon);
    const byId = items.every((i) => i && typeof i === "object" && "id" in (i as object));
    return byId ? [...items].sort((a, b) => String((a as { id: string }).id).localeCompare(String((b as { id: string }).id))) : items;
  }
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, canon(v)]));
  }
  return value;
}

type Golden = Record<string, Record<string, Record<string, unknown>>>;

for (const [modelId, g] of Object.entries(golden as unknown as Golden)) {
  describe(`${modelId} matches the Python engine`, () => {
    const m = MODELS.get(modelId)!;

    it("has the same loops (id, type, variable order, link order)", () => {
      const mine = m.loops.map(({ id, type, name, variables, edges }) => ({ id, type, name, variables, edges }));
      expect(canon(mine)).toEqual(canon(g.loops));
    });
    // The overview gained fields for uploaded models; the original ones must be unchanged.
    it("overview", () => {
      const mine = m.overview();
      const original = Object.fromEntries(Object.keys(g.overview).map((k) => [k, mine[k]]));
      expect(canon(original)).toEqual(canon(g.overview));
    });
    it("behavior", () => expect(m.behavior()).toEqual({ ...g.behavior, note: undefined }));
    it("layout", () => expect(m.layout()).toEqual(g.layout));

    it.each(Object.keys(g.resolve))("resolve %s", (q) => expect(m.resolve(q)).toEqual(g.resolve[q]));
    it.each(Object.keys(g.variable))("variable %s", (q) => expect(canon(m.variable(q))).toEqual(canon(g.variable[q])));
    it.each(Object.keys(g.loop))("loop %s", (q) => expect(canon(m.loop(q))).toEqual(canon(g.loop[q])));
    it.each(Object.keys(g.find_loops))("findLoops %s", (q) => {
      expect(m.findLoops(q).map((l) => l.id).sort()).toEqual([...(g.find_loops[q] as unknown as string[])].sort());
    });
    // "deer|deer" is deliberately different: NetworkX returned a one-node "path" that read as nonsense.
    it.each(Object.keys(g.path).filter((k) => k.split("|")[0] !== k.split("|")[1]))("path %s", (key) => {
      const [a, b] = key.split("|");
      expect(m.path(a, b)).toEqual(g.path[key]);
    });
  });
}

describe("asking for a path from a variable to itself", () => {
  it("says so instead of returning a one-node path", () => {
    const r = MODELS.get("deer-population")!.path("deer", "deer population");
    expect(r.same_variable).toBe(true);
    expect(r.paths).toBeUndefined();
  });
});
